//! 🎬️ Writes stream provenance, signed rational words and exact ordered sample bytes.
use crate::standards::v1::subsets::video::schema::snapshot::{SemioVideoSnapshot,SemioVideoStream,SemioVideoSample,SemioVideoStreamKind};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_encoding::{self,Writer};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl,ValueError};
pub(crate) fn encode(snapshot:&SemioVideoSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,ValueError>{native_encoding::encode(encoding,"semio stdio.semio.video.dsl v1\n","stdio.semio.video.pack v1",control,|writer,encoding|fields(snapshot,writer,encoding))}
fn sample(value:&SemioVideoSample,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;writer.fixed_u64(value.pts,encoding)?;writer.delimiter(b",",encoding)?;writer.byte(if encoding==SnapshotEncoding::Binary{u8::from(value.key)}else if value.key{b'1'}else{b'0'})?;writer.delimiter(b",",encoding)?;writer.octets(&value.data,encoding)?;writer.delimiter(b"]",encoding)}
fn stream(value:&SemioVideoStream,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;writer.byte(if encoding==SnapshotEncoding::Binary{crate::standards::v1::subsets::video::io::binary::snapshot::kind_tag(value.kind)}else{match value.kind{SemioVideoStreamKind::Video=>b'V',SemioVideoStreamKind::Audio=>b'A',SemioVideoStreamKind::Subtitle=>b'S'}})?;writer.delimiter(b",",encoding)?;writer.string(&value.codec,encoding)?;writer.delimiter(b",",encoding)?;writer.fixed_u32(value.width,encoding)?;writer.delimiter(b",",encoding)?;writer.fixed_u32(value.height,encoding)?;writer.delimiter(b",[",encoding)?;writer.signed64(value.rate.num,encoding)?;writer.delimiter(b",",encoding)?;writer.signed64(value.rate.den,encoding)?;writer.delimiter(b"],",encoding)?;writer.list(&value.samples,encoding,|writer,value|sample(value,writer,encoding))?;writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioVideoSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?;}else{writer.bytes(b"schema=")?;}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\nstreams=",encoding)?;writer.list(&snapshot.streams,encoding,|writer,value|stream(value,writer,encoding))}
